// SPDX-License-Identifier: MIT
pragma solidity ^0.8.7;
import "./IBEP20.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

library Shared{
    struct advert{
        address payable owner;
        uint amount;
        address asset;
        uint balance;
        bool closed;
    }
}


contract Advert is Initializable{
    
    event Funded(string __advertId,uint __amount);
    event AdvertClosed(string advertId);
    event Deposited(string advertId,uint amount,uint balance);
    event AssetTransferred(string tradeId, string advertId,uint amount,address buyer);
    event UpdatedBalance(string advertId,uint balance);
    address ADMIN_ADDRESS;
    

    mapping(string=>Shared.advert) public Adverts;
    Shared.advert [] internal ads;

    function initialize (address admin)public initializer{
        ADMIN_ADDRESS = admin;
    }

    //creating a sell ad
    function createAdvert (string memory _advertId,uint _amount, address _asset) external payable{
        require(_amount > 0, "initial deposit cannot be null");
        IBEP20(_asset).transferFrom(msg.sender, address(this), _amount);
        Shared.advert memory _ad = Shared.advert(payable(msg.sender),_amount,_asset,_amount,false);
		ads.push(_ad);
        Adverts[_advertId] = _ad;
        emit Funded(_advertId,_amount);
    }

    // adding more funds to the ad
    function deposit(string memory advertId,uint _amount) external payable{
        Shared.advert storage ad = Adverts[advertId];
        require(msg.sender == ad.owner, "unauthorized to deposit"); 
         Adverts[advertId].balance += _amount;
        IBEP20(ad.asset).transferFrom(msg.sender, address(this), _amount);
        emit Deposited(advertId,_amount,Adverts[advertId].balance);
    }

    receive() external payable{}

   function getAdvertOwner(string memory __advertId) view external returns (address){
       return (Adverts[__advertId].owner);
   }

   function closeAdvert(string memory __advertId)external{
       require(Adverts[__advertId].closed == false);
       Adverts[__advertId].closed == true;
   }


    function addBalance(string memory __advertId, uint __amount)external {
        Shared.advert storage _ad = Adverts[__advertId];
        require(_ad.closed == false,"advert is closed");
        _ad.balance += __amount;
        emit UpdatedBalance(__advertId, _ad.balance);
    }

    function deductBalance(string memory __advertId,uint __amount) external {
        Shared.advert storage _ad = Adverts[__advertId];
        require(_ad.closed == false,"advert is closed");
        require(_ad.balance >= __amount,"insufficient balance");
        _ad.balance -= __amount;
        emit UpdatedBalance(__advertId, _ad.balance);
    }


    function transferAsset(string memory tradeId,string memory advertId,address payable seller,address payable buyer,uint _amount) external{
        Shared.advert storage ad = Adverts[advertId];
		require(payable(seller) == ad.owner,"Unauthorized to make transfer");
        IBEP20(ad.asset).transfer(buyer,_amount);
        emit AssetTransferred(tradeId,advertId,_amount, buyer);
    }

    function adminTransferAsset(string memory _advertId,address admin,address payable _reciepient,uint _amount) external{
        require(admin == ADMIN_ADDRESS,"Unauthorized to make transacton");
        Shared.advert storage _ad = Adverts[_advertId];
        IBEP20(_ad.asset).transfer(_reciepient, _amount);
        _ad.balance -= _amount;
        emit UpdatedBalance(_advertId, _ad.balance);
    }

    function getBalance(string memory advertId) external view returns (uint){
        return (Adverts[advertId].balance);
    }
	
	function getOwner(string memory advertId) external view returns (address){
        return (Adverts[advertId].owner);
    }
}
